14	/**
15	 * The four rules of Conway's Game of Life, in the specification's own terms.
16	 *
17	 * Rule 1 – underpopulation: a live cell with fewer than 2 live neighbors dies.
18	 * Rule 3 – overpopulation: a live cell with more than 3 live neighbors dies.
19	 * Both are expressed here as the surviving band they carve out, so that every
20	 * rule participates in the decision rather than sitting unused as a comment.
21	 */
22	const survivesUnderpopulation = (liveNeighbors: number): boolean => liveNeighbors >= 2;
23	
24	const survivesOverpopulation = (liveNeighbors: number): boolean => liveNeighbors <= 3;
25	
26	/** Rule 2 – survival: a live cell with 2 or 3 live neighbors lives on. */
27	const survives = (liveNeighbors: number): boolean =>
28	  survivesUnderpopulation(liveNeighbors) && survivesOverpopulation(liveNeighbors);
29	
30	/** Rule 4 – reproduction: a dead cell with exactly 3 live neighbors becomes alive. */
31	const isBorn = (liveNeighbors: number): boolean => liveNeighbors === 3;
32	
33	const livesOn = (isAlive: boolean, liveNeighbors: number): boolean =>
34	  isAlive ? survives(liveNeighbors) : isBorn(liveNeighbors);
35	
36	/**
37	 * Every cell that could be alive next generation — each live cell's neighbors —
38	 * paired with how many live neighbors it has. Cells with no live neighbor at all
39	 * are omitted: they are dead now and stay dead, by all four rules.
40	 */
41	function liveNeighborCounts(cells: Cell[]): Map<string, { cell: Cell; count: number }> {
42	  const counts = new Map<string, { cell: Cell; count: number }>();
43	  for (const [x, y] of cells) {
44	    for (const neighbor of neighborsOf(x, y)) {
45	      const key = cellKey(...neighbor);
46	      const entry = counts.get(key) ?? { cell: neighbor, count: 0 };
47	      entry.count += 1;
48	      counts.set(key, entry);
49	    }
50	  }
